#include <iostream>
#include <map>
#include <string>

class ConsistentHashRing {
private:
    // A map representing our circular ring: RingPosition -> ServerName
    std::map<int, std::string> ring;

    // Helper hash function
    int getHash(std::string key) {
        // A simple hash function for demonstration
        unsigned int hash = 0;
        for (char c : key) {
            hash = hash * 31 + c;
        }
        return hash % 360; // Map keys to a 360-degree circle
    }

public:
    // Add server to the ring
    void addServer(std::string serverName) {
        int pos = getHash(serverName);
        ring[pos] = serverName;
        std::cout << "Server " << serverName << " added at position " << pos << "\n";
    }

    // Route key to the nearest server clockwise
    std::string routeKey(std::string key) {
        if (ring.empty()) return "No servers available";

        int keyPos = getHash(key);

        // Find the first server position >= keyPos
        auto it = ring.lower_bound(keyPos);

        // If we reached the end of the map, wrap around to the first server (circle effect)
        if (it == ring.end()) {
            it = ring.begin();
        }

        return it->second;
    }
};
